// GENERATED by api/scripts/gen.ts (npm run gen) from the schema and config files. Do not edit by hand.
// The edge runtime cannot read the repository, so the texts the API needs at runtime live here.

export interface TextFile {
  path: string;
  text: string;
}

/** schema/schema.tql, schema/functions.tql, then each migration in number order: what built the database. */
export const SCHEMA_FILES: TextFile[] = [
  { path: "schema/schema.tql", text: "# Project Apex: TypeDB 3.x schema (types, attributes, relations and roles).\n# Saved queries (functions) are in functions.tql. Explained in docs/schema-design.md.\n# Run in a SCHEMA transaction on a new database: uv run python -m scripts.create_database\n\ndefine\n\n# ---- attributes ------------------------------------------------------------------------\nattribute code, value string;                 # stable readable ID; unique across the database\nattribute name, value string;\nattribute description, value string;\nattribute job-title, value string;\nattribute jurisdiction, value string;\nattribute sector, value string;\nattribute deal-value, value decimal;          # exact money, never floating point\nattribute currency, value string @values(\"GBP\", \"USD\", \"EUR\");\nattribute deal-structure, value string;\nattribute as-of-date, value date;             # the demo's \"today\", stored in the data\nattribute status, value string @values(\"not-started\", \"in-progress\", \"at-risk\", \"delayed\", \"complete\");\nattribute criticality, value string @values(\"low\", \"medium\", \"high\", \"critical\");\nattribute planned-start, value date;\nattribute due-date, value date;\nattribute baseline-due-date, value date;\nattribute completed-date, value date;\nattribute progress, value integer @range(0..100);\nattribute lag-days, value integer @range(0..365);\nattribute legal-basis, value string;\nattribute review-phase, value string;\nattribute consequence, value string;          # what happens if an obligation is not met\nattribute mandate-type, value string;\nattribute occurred-at, value datetime;\nattribute summary, value string;\nattribute event-kind, value string;\nattribute stake, value decimal @range(0.0dec..1.0dec);   # 0.6 = 60%\n\n# ---- parties ---------------------------------------------------------------------------\nentity party @abstract, owns code @key, owns name, owns description,\n  plays raci-assignment:holder, plays deal-event:actor;\nentity person sub party, plays employment:employee;\nentity organisation @abstract, sub party, owns jurisdiction, owns sector,\n  plays employment:employer, plays bound-by:obligor, plays consent-right:grantor;\nentity company sub organisation,\n  plays acquisition:acquirer, plays acquisition:target, plays mandate:client,\n  plays financing:borrower, plays authority-review:applicant,\n  plays ownership:owner, plays ownership:owned;\nentity financial-institution @abstract, sub organisation, plays financing:lender;\nentity investment-bank sub financial-institution, plays mandate:adviser;\nentity commercial-bank sub financial-institution;\nentity professional-services-firm @abstract, sub organisation, plays mandate:adviser;\nentity law-firm sub professional-services-firm;\nentity accounting-firm sub professional-services-firm;\nentity consultancy sub professional-services-firm;\nentity communications-firm sub professional-services-firm;\nentity authority @abstract, sub organisation, plays authority-review:reviewer;\nentity regulator sub authority;\nentity court sub authority;\n\n# ---- work ------------------------------------------------------------------------------\nentity deal-item @abstract, owns code @key, owns name, owns description, owns status,\n  owns criticality, owns planned-start, owns due-date, owns baseline-due-date,\n  owns completed-date, owns progress,\n  plays deal-scope:item, plays work-breakdown:part @card(0..1),\n  plays dependency:prerequisite, plays dependency:dependent,\n  plays deadline-limit:limited-item,\n  plays raci-assignment:item, plays accountability:accountable-item @card(0..1),\n  plays deal-event:subject;\nentity workstream sub deal-item, plays work-breakdown:whole;\nentity milestone sub deal-item;\nentity obligation @abstract, sub deal-item, owns legal-basis, owns consequence,\n  plays bound-by:obligation, plays consent-right:obligation;\nentity condition sub obligation;\nentity regulatory-clearance sub condition, plays authority-review:subject;\nentity shareholder-approval sub condition;\nentity court-sanction sub condition, plays authority-review:subject;\nentity covenant sub obligation;\nentity deadline sub obligation, plays deadline-limit:deadline;\n\n# ---- relations -------------------------------------------------------------------------\nrelation transaction @abstract, relates buyer, relates seller,\n  owns code @key, owns name, owns description, owns deal-value, owns currency,\n  owns deal-structure, owns as-of-date,\n  plays deal-scope:deal, plays mandate:engagement, plays financing:purpose;\nrelation acquisition sub transaction, relates acquirer as buyer, relates target as seller;\nrelation employment, relates employee, relates employer, owns job-title;\nrelation mandate, relates client, relates adviser, relates engagement,\n  owns code @key, owns mandate-type, plays raci-assignment:via;\nrelation financing, relates borrower, relates lender, relates purpose,\n  owns code @key, owns name, owns deal-value, owns currency;\nrelation deal-scope, relates deal, relates item;\nrelation work-breakdown, relates whole, relates part;\nrelation authority-review, relates reviewer, relates subject, relates applicant,\n  owns legal-basis, owns review-phase;\nrelation bound-by, relates obligor, relates obligation;\nrelation consent-right, relates grantor, relates obligation;\nrelation deadline-limit, relates limited-item, relates deadline;\nrelation ownership, relates owner, relates owned, owns stake;\nrelation dependency @abstract, relates prerequisite, relates dependent, owns lag-days;\nrelation hard-dependency @abstract, sub dependency;\nrelation gating sub hard-dependency;          # a condition must be met first\nrelation sequencing sub hard-dependency;      # X must finish before Y\nrelation informing sub dependency;            # soft: Y needs input from X; dates don't move\nrelation raci-assignment @abstract, relates holder, relates item, relates via @card(0..1);\nrelation responsibility sub raci-assignment;                                   # R\nrelation accountability sub raci-assignment, relates accountable-item as item; # A\nrelation consultation sub raci-assignment;                                     # C\nrelation notification sub raci-assignment;                                     # I\nrelation deal-event, relates actor, relates subject, owns occurred-at, owns summary, owns event-kind;\n" },
  { path: "schema/functions.tql", text: "# Project Apex: saved queries (functions), stored in the schema so every query can call them.\n# Explained in docs/schema-design.md §5. Loaded after schema.tql, in a SCHEMA transaction.\n\ndefine\n\n# Everything whose dates move if $start moves: follows hard dependencies to any depth.\n# Reachability only (no value carried), so it is safe on cycles.\nfun downstream($start: deal-item) -> { deal-item }:\n  match\n    { hard-dependency (prerequisite: $start, dependent: $next); }\n    or { let $mid in downstream($start); hard-dependency (prerequisite: $mid, dependent: $next); };\n  return { $next };\n\n# The same walk, returning each step with its dependency (so callers can read lag-days).\nfun impact_edges($start: deal-item) -> { deal-item, hard-dependency, deal-item }:\n  match\n    { $d isa hard-dependency (prerequisite: $from, dependent: $to); $from is $start; }\n    or { let $p, $e, $from in impact_edges($start);\n         $d isa hard-dependency (prerequisite: $from, dependent: $to); };\n  return { $from, $d, $to };\n\n# Everything that must happen before $end (\"what is blocking completion?\").\nfun upstream($end: deal-item) -> { deal-item }:\n  match\n    { hard-dependency (prerequisite: $prev, dependent: $end); }\n    or { let $mid in upstream($end); hard-dependency (prerequisite: $prev, dependent: $mid); };\n  return { $prev };\n\n# The one Accountable party for an item (the schema allows at most one).\nfun accountable_for($item: deal-item) -> party:\n  match accountability (holder: $p, accountable-item: $item);\n  return first $p;\n\n# Every company $parent holds, at any depth, with the effective stake along EACH route.\n# A company reached by two routes comes back twice: callers sum them.\n# Only correct when ownership has no cycles: always run ownership_cycles() and the\n# over-100% check first (apex/queries.py does this).\nfun group_members($parent: company) -> { company, decimal }:\n  match\n    { ownership (owner: $parent, owned: $sub), has stake $s; let $eff = $s; }\n    or { let $mid, $m in group_members($parent);\n         ownership (owner: $mid, owned: $sub), has stake $s; let $eff = $m * $s; };\n  return { $sub, $eff };\n\n# Everyone above $c in the ownership chain. Reachability only: safe on cycles.\nfun owners_above($c: company) -> { company }:\n  match\n    { ownership (owner: $o, owned: $c); }\n    or { let $mid in owners_above($c); ownership (owner: $o, owned: $mid); };\n  return { $o };\n\n# Companies that (indirectly) own themselves. Must always be empty.\nfun ownership_cycles() -> { company }:\n  match $c isa company; let $o in owners_above($c); $o is $c;\n  return { $c };\n" },
  { path: "schema/migrations/001-phase6-foundation.tql", text: "# Migration 001 (Phase 6A.2): the data foundation for the Workstreams, Parties and Gantt views.\n# Additions only: every type, role and attribute from schema.tql is unchanged, so existing queries keep\n# working. Loaded after schema.tql and functions.tql (apex/database.py). Explained in docs/schema-design.md.\n\ndefine\n\n# ---- attributes ------------------------------------------------------------------------\nattribute actual-start-date, value date;      # when work really began (bars start here if known)\nattribute response-due-date, value date;      # when an answer to a request is expected\nattribute email, value string;                # fictional only: reserved .example domains\nattribute phone, value string;                # fictional only: Ofcom drama range 07700 900xxx\nattribute automated, value boolean;           # a system-generated notification, not a person writing\nattribute previous-status, value string @values(\"not-started\", \"in-progress\", \"at-risk\", \"delayed\", \"complete\");\nattribute new-status, value string @values(\"not-started\", \"in-progress\", \"at-risk\", \"delayed\", \"complete\");\nattribute likelihood, value string @values(\"low\", \"medium\", \"high\");\nattribute severity, value string @values(\"low\", \"medium\", \"high\", \"critical\");\nattribute risk-status, value string @values(\"open\", \"mitigating\", \"closed\");\nattribute mitigation, value string;\n\n# ---- work: activities have a duration; milestones are points in time ----------------------\nentity activity sub deal-item;\nentity deal-item, owns actual-start-date;\n\n# ---- people and organisations ------------------------------------------------------------\nentity person, owns email @unique, owns phone @unique;\nentity registrar sub professional-services-firm;        # share registrar / receiving agent\nrelation ownership, owns description;                   # why a holding exists, minority rights\n\n# ---- activity history: what happened, and what counts as engagement ----------------------\n# Every event keeps deal-event's roles (actor, subject) and attributes; queries on deal-event see all.\nrelation deal-event, owns code @key;\n# engagement and outreach group their subtypes. They can't be @abstract because deal-event (Phase 1) isn't,\n# and TypeDB requires an abstract type's parent to be abstract; the loader never inserts them directly.\nrelation engagement sub deal-event;                     # counts as a meaningful response by the actor\nrelation response sub engagement, plays reply:answer;   # answers a request\nrelation meeting sub engagement, relates attendee @card(0..);   # attended by people or organisations (any number)\nrelation delivery sub engagement;                       # a deliverable submitted: report, filing, draft\nrelation decision sub engagement;                       # an approval, sign-off, signature or clearance\nrelation outreach sub deal-event, relates recipient @card(0..);   # does not count as engagement by its recipients\nrelation request sub outreach, owns response-due-date, plays reply:original;\nrelation notice sub outreach, owns automated;            # an outbound notice (automated or not)\nrelation status-change sub deal-event, owns previous-status, owns new-status;\nrelation reply, relates original, relates answer;       # a relation between two relations\nentity party, plays outreach:recipient, plays meeting:attendee;\n\n# ---- risk register -------------------------------------------------------------------------\nentity risk, owns code @key, owns name, owns description, owns likelihood, owns severity,\n  owns risk-status, owns mitigation,\n  plays risk-exposure:risk, plays risk-ownership:owned-risk;\nrelation risk-exposure, relates risk, relates exposed;  # which work a risk threatens\nrelation risk-ownership, relates risk-owner, relates owned-risk @card(1..1);\nentity deal-item, plays risk-exposure:exposed;\nentity party, plays risk-ownership:risk-owner;\n" },
  { path: "schema/migrations/002-meeting-agenda.tql", text: "# Migration 002 (Phase 6E data): a meeting can name the work items it actually discussed.\n# A workstream steering meeting is recorded against the workstream (oversight); its agenda items say\n# which activities were discussed, so attending it is engagement on those items only, never on every\n# item in the workstream (docs/phase6-plan.md §18).\n\ndefine\n  relation meeting, relates agenda-item @card(0..);\n  entity deal-item, plays meeting:agenda-item;\n" },
];

export const ENGAGEMENT_POLICY_YAML = "# Engagement policy (decision D9, docs/phase6-plan.md §5.3 and §12). Configuration, not business data:\n# changing it never touches a TypeDB record. Every \"days\" figure is counted from the scenario date\n# stored in TypeDB (26 Oct 2026), never from today's real date. Served read-only at /api/engagement-policy.\n\n# Days without engagement on an assigned, active item before the assignment turns amber or red,\n# by RACI letter. Only the letters listed are assessed for inactivity: Accountable and Responsible people\n# are expected to act; Consulted and Informed people act when asked, so they are assessed on the requests\n# sent to them (below), never on silence. (Phase 6D deviation from the plan's C and I thresholds, which\n# were C 8/15 and I 31/46 days: add these lines back to restore them.)\ninactivity:\n  A: {amber_from: 4, red_from: 8}\n  R: {amber_from: 4, red_from: 8}\n\n# A request addressed to someone with a reply-by date: red once that date has passed with no response\n# recorded; amber when it falls due within this many days.\nresponse_warning_days: 2\n\n# When an item becomes active, so that its inactivity clock starts: its actual start, else its planned\n# start; a point milestone or condition (no start date) becomes active this many days before it is due.\nmilestone_active_window_days: 21\n\n# Escalation (one step, amber to red; never green to amber, so an engaged person is not flagged for\n# the item's own difficulty, which is shown separately as delivery risk). Applies when the item is\n# schedule-critical or recorded as critical, AND it is due within the urgent window or is at risk or delayed.\nurgent_window_days: 14\n\n# Schedule float: the largest delay an item can absorb before any contractual deadline is breached\n# (the Impact Explorer's projection). At or below these, an item is schedule-critical / near-critical.\ncritical_float_days: 30\nnear_critical_float_days: 60\n\n# Authorities (regulators, courts) are assessed against their statutory timetable and the requests sent\n# to them, never against silence. A decision due within this many days with none recorded is amber.\nstatutory_warning_days: 10\n";

export const CONNECTION_POLICY_YAML = "# Connection paths (decision D12, docs/phase6-plan.md §7 and §18). Configuration, not business data.\n#\n# A path alternates thing → relation → thing. Stepping stones are always entities (people, organisations,\n# work items, risks): the acquisition, mandates and events are relations in the schema, so \"A is on the\n# deal and so is B\" can never be a path. Paths are ranked by cost, lowest first:\n#   cost = hop_cost × hops + Σ relation weight + Σ hub_penalty × log2(1 + links of each stepping stone)\n\nhop_cost: 1.0\nhub_penalty: 0.25\n\n# Light for specific facts, heavier for generic context, and heaviest for activity records, so a standing\n# relationship outranks a one-off interaction. Every type stays usable; weights only rank.\nrelation_weights:\n  acquisition: 0.0\n  mandate: 0.0\n  financing: 0.0\n  authority-review: 0.0\n  ownership: 0.0\n  consent-right: 0.0\n  bound-by: 0.0\n  deadline-limit: 0.0\n  risk-exposure: 0.0\n  risk-ownership: 0.0\n  accountability: 0.1\n  responsibility: 0.1\n  gating: 0.1\n  sequencing: 0.1\n  consultation: 0.4\n  notification: 0.5\n  informing: 0.4\n  employment: 0.5\n  request: 1.4\n  response: 1.4\n  meeting: 1.6\n  delivery: 1.6\n  decision: 1.4\n  notice: 2.0\n  status-change: 2.0\n  work-breakdown: 1.2\n\n# Bounds, so results are never silently partial: the middle query (three steps) is capped, the request has\n# a time budget, and the answer reports any cap or skipped depth.\nmax_hops: 3\nrow_cap: 2000\nbudget_ms: 1500\ndefault_results: 20\nmax_results: 50\n# Activity records (meetings, requests and other events) are interactions, not standing relationships:\n# they may be a step in paths of up to this many hops only.\nevent_max_hops: 2\n# A stepping stone with at least this many links is called out as a hub in the path's notes.\nhub_note_links: 60\n";
